int uniquePaths(int m, int n) {
    vector<int> dp(n, 1);                 // one row instead of the full grid
    for (int i = 1; i < m; i++)
        for (int j = 1; j < n; j++)
            dp[j] += dp[j - 1];           // dp[j] is the row above, dp[j-1] is the left
    return dp[n - 1];
}

